    configuration.set(PropertiesDrivenCryptoFactory.COLUMN_KEYS_PROPERTY_NAME, "column-key:value");
    configuration.set("parquet.encryption.key.material.internal", "false");

    ParquetCryptoRuntimeException exception =
        assertThrows(
            ParquetCryptoRuntimeException.class,
