    assertEquals("Output file path cannot be null", exception.getMessage());
  }

  @Test
  void rejectsNullConfiguration() {
    assertThrows(
        NullPointerException.class,
        () -> factory.getFileEncryptionProperties(null, OUTPUT_PATH, writeContext()));
  }
